    public function setTipoComInternas(PropelCollection $tipoComInternas, PropelPDO $con = null)
    {
        $tipoComInternasToDelete = $this->getTipoComInternas(new Criteria(), $con)->diff($tipoComInternas);


        $this->tipoComInternasScheduledForDeletion = $tipoComInternasToDelete;

        foreach ($tipoComInternasToDelete as $tipoComInternaRemoved) {
            $tipoComInternaRemoved->setPlantillasCom(null);
        }

        $this->collTipoComInternas = null;
        foreach ($tipoComInternas as $tipoComInterna) {
            $this->addTipoComInterna($tipoComInterna);
        }

        $this->collTipoComInternas = $tipoComInternas;
        $this->collTipoComInternasPartial = false;

