    public function countTipoComInternas(Criteria $criteria = null, $distinct = false, PropelPDO $con = null)
    {
        $partial = $this->collTipoComInternasPartial && !$this->isNew();
        if (null === $this->collTipoComInternas || null !== $criteria || $partial) {
            if ($this->isNew() && null === $this->collTipoComInternas) {
                return 0;
            }

            if ($partial && !$criteria) {
                return count($this->getTipoComInternas());
            }
            $query = TipoComInternaQuery::create(null, $criteria);
            if ($distinct) {
                $query->distinct();
