            if ($this->tipoComInternasScheduledForDeletion and $this->tipoComInternasScheduledForDeletion->contains($l)) {
                $this->tipoComInternasScheduledForDeletion->remove($this->tipoComInternasScheduledForDeletion->search($l));
            }
        }

        return $this;
    }

