    public function removeTipoComInterna($tipoComInterna)
    {
        if ($this->getTipoComInternas()->contains($tipoComInterna)) {
            $this->collTipoComInternas->remove($this->collTipoComInternas->search($tipoComInterna));
            if (null === $this->tipoComInternasScheduledForDeletion) {
                $this->tipoComInternasScheduledForDeletion = clone $this->collTipoComInternas;
                $this->tipoComInternasScheduledForDeletion->clear();
            }
            $this->tipoComInternasScheduledForDeletion[]= $tipoComInterna;
            $tipoComInterna->setPlantillasCom(null);
        }

        return $this;
    }

