    /**
     * Resets all references to other model objects or collections of model objects.
     *
     * This method is a user-space workaround for PHP's inability to garbage collect
     * objects with circular references (even in PHP 5.3). This is currently necessary
     * when using Propel in certain daemon or large-volume/high-memory operations.
     *
     * @param boolean $deep Whether to also clear the references on all referrer objects.
     */
    public function clearAllReferences($deep = false)
    {
        if ($deep && !$this->alreadyInClearAllReferencesDeep) {
            $this->alreadyInClearAllReferencesDeep = true;
            if ($this->collComEnviadas) {
                foreach ($this->collComEnviadas as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collComenviadaMasivass) {
                foreach ($this->collComenviadaMasivass as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collPlantillascomServicios) {
                foreach ($this->collPlantillascomServicios as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collTipoComInternas) {
                foreach ($this->collTipoComInternas as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->aModulo instanceof Persistent) {
              $this->aModulo->clearAllReferences($deep);
            }
            if ($this->aDependencia instanceof Persistent) {
              $this->aDependencia->clearAllReferences($deep);
            }
            if ($this->aRegional instanceof Persistent) {
              $this->aRegional->clearAllReferences($deep);
            }

            $this->alreadyInClearAllReferencesDeep = false;
        } // if ($deep)

        if ($this->collComEnviadas instanceof PropelCollection) {
            $this->collComEnviadas->clearIterator();
        }
        $this->collComEnviadas = null;
        if ($this->collComenviadaMasivass instanceof PropelCollection) {
            $this->collComenviadaMasivass->clearIterator();
        }
        $this->collComenviadaMasivass = null;
        if ($this->collPlantillascomServicios instanceof PropelCollection) {
            $this->collPlantillascomServicios->clearIterator();
        }
        $this->collPlantillascomServicios = null;
        if ($this->collTipoComInternas instanceof PropelCollection) {
            $this->collTipoComInternas->clearIterator();
        }
        $this->collTipoComInternas = null;
        $this->aModulo = null;
        $this->aDependencia = null;
        $this->aRegional = null;
    }

